*{box-sizing:border-box;margin:0;padding:0}
html,body{width:1080px;height:1920px;overflow:hidden;background:#050B14}
#stage{position:relative;width:1080px;height:1920px;overflow:hidden;font-family:'Plus Jakarta Sans','Inter',sans-serif;color:#fff}
.scene{position:absolute;inset:0;display:none;will-change:transform,opacity}
.bg{position:absolute;inset:0}
.bg-blue{background:radial-gradient(120% 70% at 50% 18%,#0E6FA8 0%,#08486E 38%,#0A1A2E 75%,#050B14 100%)}
.bg-night{background:radial-gradient(90% 60% at 75% 10%,#3B3486 0%,#1E1B4B 45%,#0B1026 100%)}
.bg-warm{background:linear-gradient(180deg,#FFF1DA 0%,#FFE0B0 55%,#FDBA74 100%)}
.bg-dark{background:radial-gradient(100% 60% at 50% 40%,#1B2436 0%,#0A0F1A 70%,#04070D 100%)}
.dots{position:absolute;inset:0;background-image:radial-gradient(rgba(255,255,255,.07) 2px,transparent 2.5px);background-size:44px 44px}
.title{position:absolute;left:70px;right:70px;top:210px;font-weight:800;font-size:88px;line-height:1.04;letter-spacing:-2px}
.title .hl{color:#FBBF24}
.title .bl{color:#7DD3FC}
.row{display:flex;align-items:center;gap:26px}
.badge{width:132px;height:132px;border-radius:50%;background:#FBBF24;color:#0F172A;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:86px;box-shadow:0 12px 40px rgba(251,191,36,.45);flex:none}
.steptitle{position:absolute;left:66px;right:60px;top:200px}
.steptitle h1{font-size:82px;font-weight:800;line-height:1.02;letter-spacing:-2px}
.pill{display:inline-flex;align-items:center;gap:14px;border-radius:999px;padding:14px 28px;font-weight:800;font-size:40px}
.phone{position:absolute;left:240px;top:560px;width:600px;height:1262px;border-radius:86px;padding:16px;transform-origin:50% 40%;
 background:linear-gradient(135deg,#6b717b 0%,#2a2e35 12%,#1b1e23 40%,#2d3138 75%,#787f8a 100%);
 box-shadow:0 70px 140px rgba(0,0,0,.55),0 25px 45px rgba(0,0,0,.35),0 0 0 1.5px #0a0b0d,inset 0 0 0 1.5px rgba(255,255,255,.35),inset 0 0 0 4px #101114,inset 0 0 0 12px #050506}
.phone::before{content:"";position:absolute;inset:3px;border-radius:83px;border:1px solid rgba(255,255,255,.08);pointer-events:none}
.pbtn{position:absolute;width:7px;border-radius:3px;background:linear-gradient(90deg,#1c1f24,#7b828c 55%,#2a2e35)}
.screen{position:relative;width:568px;height:1230px;border-radius:70px;overflow:hidden;background:#fff;box-shadow:0 0 0 2px #000}
.screen .shot{position:absolute;left:0;top:128px;width:568px;height:1102px;overflow:hidden;background:#F8FAFC}
.screen .shot img{position:absolute;left:0;top:0;width:568px;transform-origin:0 0}
.chrome{position:absolute;left:0;right:0;top:48px;height:80px;background:#fff;border-bottom:1px solid #E5E7EB;display:flex;align-items:center;gap:16px;padding:0 20px;z-index:3}
.chrome .url{flex:1;height:54px;border-radius:27px;background:#F1F3F4;display:flex;align-items:center;gap:10px;padding:0 18px;font:500 24px Inter;color:#202124}
.gbar{position:absolute;left:50%;bottom:12px;width:150px;height:6px;margin-left:-75px;border-radius:3px;background:rgba(0,0,0,.6);z-index:40}
.gbar.light{background:rgba(255,255,255,.85)}
.glare{position:absolute;inset:0;border-radius:70px;background:linear-gradient(118deg,rgba(255,255,255,.13) 0%,rgba(255,255,255,.04) 22%,rgba(255,255,255,0) 38%,rgba(255,255,255,0) 80%,rgba(255,255,255,.05) 100%);pointer-events:none;z-index:45}
.sbar{position:absolute;left:0;right:0;top:0;height:48px;background:#fff;color:#111;font:600 23px Inter;display:flex;align-items:center;justify-content:space-between;padding:4px 40px 0 44px;z-index:6}
.sbar.dark{background:transparent;color:#fff}
.island{position:absolute;left:50%;top:27px;width:32px;height:32px;margin-left:-16px;border-radius:50%;z-index:50;background:radial-gradient(circle at 42% 40%,#3b5168 0,#121a24 28%,#05070a 55%,#000 70%);box-shadow:0 0 0 3px #0c0d10,inset 0 0 4px rgba(120,160,200,.35)}
.ring{position:absolute;border:7px solid #FBBF24;border-radius:24px;box-shadow:0 0 0 9999px rgba(15,23,42,.0),0 0 34px rgba(251,191,36,.9);z-index:4;opacity:0}
.tap{position:absolute;width:96px;height:96px;margin:-48px 0 0 -48px;border-radius:50%;background:rgba(255,255,255,.9);box-shadow:0 6px 24px rgba(0,0,0,.45);z-index:20;opacity:0}
.tap::after{content:"";position:absolute;inset:-6px;border-radius:50%;border:6px solid #fff;opacity:var(--r,0);transform:scale(var(--rs,1))}
.chip{position:absolute;background:#fff;color:#0F172A;border-radius:30px;box-shadow:0 18px 50px rgba(0,0,0,.35);padding:22px 26px;font-weight:800}
.toast{position:absolute;left:50%;transform:translateX(-50%);background:#047857;color:#fff;border-radius:999px;padding:16px 30px;font:800 30px 'Plus Jakarta Sans';white-space:nowrap;z-index:6;opacity:0;box-shadow:0 10px 30px rgba(0,0,0,.3)}
.notif{position:absolute;background:rgba(255,255,255,.97);color:#0F172A;border-radius:34px;padding:24px 28px;display:flex;gap:22px;align-items:center;box-shadow:0 24px 60px rgba(0,0,0,.35)}
.notif .ic{width:86px;height:86px;border-radius:22px;background:#fff;box-shadow:inset 0 0 0 2px #E2E8F0;display:flex;align-items:center;justify-content:center;flex:none}
.notif .ic img{width:70px}
.coin{position:absolute;width:84px;height:84px;margin:-42px 0 0 -42px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#FFE68A,#F5B700 55%,#C98800);border:5px solid #B07400;color:#7A4B00;font:800 40px 'Plus Jakarta Sans';display:flex;align-items:center;justify-content:center;opacity:0;z-index:15}
.plus{position:absolute;font:800 52px 'Plus Jakarta Sans';color:#FBBF24;text-shadow:0 4px 14px rgba(0,0,0,.6);opacity:0;z-index:15;white-space:nowrap}
.av{position:absolute;width:104px;height:104px;margin:-52px 0 0 -52px;border-radius:50%;color:#fff;font:800 50px 'Plus Jakarta Sans';display:flex;align-items:center;justify-content:center;border:5px solid #fff;box-shadow:0 10px 30px rgba(0,0,0,.4);opacity:0;z-index:12}
.op{display:flex;align-items:center;justify-content:center;border-radius:26px;font:800 36px 'Plus Jakarta Sans';height:104px;padding:0 26px;box-shadow:0 14px 34px rgba(0,0,0,.35);opacity:0}
.flash{position:absolute;inset:0;background:#fff;opacity:0;z-index:30;pointer-events:none}
.vid{position:absolute;left:0;top:0;width:1080px;height:1920px;object-fit:cover}
.shade{position:absolute;left:0;right:0;top:0;height:820px;background:linear-gradient(180deg,rgba(5,11,20,.88) 0%,rgba(5,11,20,.6) 50%,rgba(5,11,20,0) 100%)}
.shadeb{position:absolute;left:0;right:0;bottom:0;height:900px;background:linear-gradient(0deg,rgba(5,11,20,.75) 0%,rgba(5,11,20,0) 100%)}
svg{display:block}

