// ===================== moteur d'animation =====================
const $=id=>document.getElementById(id);
const cl=(x,a=0,b=1)=>Math.min(b,Math.max(a,x));
const P=(t,a,d)=>cl((t-a)/d);
const eo=x=>1-Math.pow(1-x,3);
const eio=x=>x<.5?4*x*x*x:1-Math.pow(-2*x+2,3)/2;
const back=x=>{x=cl(x);const c1=1.9,c3=c1+1;return 1+c3*Math.pow(x-1,3)+c1*Math.pow(x-1,2)};
const lerp=(a,b,k)=>a+(b-a)*k;
function st(el,{o,x=0,y=0,s=1,r=0,extra=''}){if(typeof el==='string')el=$(el);if(o!==undefined)el.style.opacity=o;el.style.transform=`translate(${x}px,${y}px) scale(${s}) rotate(${r}deg) ${extra}`;}
function popIn(el,t,a,{dy=40,dur=.5}={}){const k=P(t,a,dur);st(el,{o:cl(k*2.5),y:(1-eo(k))*dy,s:lerp(.6,1,back(k))});}

// Durées des scènes (secondes). Recalées sur la voix off au montage final.
const T=window.T||{s1:[0,5],s2:[5,9],s3:[9,13.5],s4:[13.5,19],s5:[19,24.5],s6:[24.5,29],s7:[29,35],s8:[35,40],s9:[40,46.5]};
const DUR=T.s9[1];
const TR=.34; // durée des transitions

// Écran de téléphone : zoom sur un rectangle (coordonnées CSS de la page, 390 px de large)
const K=568/390, TOPB=128, SH=1230-128;
function focus(img,ring,rect,z,ringO){
  // rect = [x1,y1,x2,y2] ; z = zoom
  const cx=(rect[0]+rect[2])/2*K, cy=(rect[1]+rect[3])/2*K;
  let tx=568/2-cx*z, ty=SH*0.42-cy*z;
  tx=cl(tx,568-568*z,0); ty=cl(ty,SH-844*K*z,0);
  img.style.transform=`translate(${tx}px,${ty}px) scale(${z})`;
  if(ring){const pad=10;ring.style.left=(tx+rect[0]*K*z-pad)+'px';ring.style.top=(TOPB+ty+rect[1]*K*z-pad)+'px';
    ring.style.width=((rect[2]-rect[0])*K*z+pad*2)+'px';ring.style.height=((rect[3]-rect[1])*K*z+pad*2)+'px';ring.style.opacity=ringO;}
  return {tx,ty,z};
}
function lerpRect(a,b,k){return a.map((v,i)=>lerp(v,b[i],k));}
// position à l'écran (stage) d'un point de la page dans un téléphone
function phonePt(ph,f,px,py,phoneTop){const left=240+16, top=(phoneTop)+16+TOPB;return [left+f.tx+px*K*f.z, top+f.ty+py*K*f.z];}
function tap(el,t,a,x,y){const k=P(t,a-.35,.35),u=P(t,a,.5);const o=t<a-.35?0:(t<a+.5?1:1-P(t,a+.5,.25));
  el.style.left=x+'px';el.style.top=y+'px';const press=t>=a&&t<a+.15?.82:1;
  el.style.opacity=o;el.style.transform=`translate(${(1-eo(k))*60}px,${(1-eo(k))*80}px) scale(${press})`;
  el.style.setProperty('--r',t>=a?1-u:0);el.style.setProperty('--rs',1+u*1.4);}

// ---------- vidéos : positionnement image par image ----------
let SEEKS=[];
function vid(id,time,rate=1){const v=$(id);const d=(v.duration||10)-0.05;const tt=cl(time,0,d);
  if(Math.abs(v.currentTime-tt)>0.004){SEEKS.push(new Promise(r=>v.addEventListener('seeked',r,{once:true})));v.currentTime=tt;}}
window.videosReady=()=>[...document.querySelectorAll('video')].every(v=>v.readyState>=2);

