// ---------- transitions entre scènes ----------
function sceneWrap(id,t){
  if(!T[id]){$(id).style.display='none';return null;}
  const [a,b]=T[id],el=$(id);
  if(t<a-0.0001||(t>b+TR&&id!=='s9')){el.style.display='none';return null;}
  el.style.display='block';
  let x=0,o=1,s=1,blur=0;
  if(id!=='s1'){const k=eo(P(t,a,TR));x=(1-k)*1080;}
  if(t>b&&id!=='s9'){const e=eio(P(t,b,TR));x=-e*380;o=1-e*.6;s=1-e*.06;blur=e*8;}
  el.style.opacity=o;el.style.transform=`translateX(${x}px) scale(${s})`;el.style.filter=blur?`blur(${blur}px)`:'none';
  el.style.zIndex=t>b?1:2;
  return t-a;
}
